package org.telegram.messenger.tetogram;
import org.junit.Test;
import static org.junit.Assert.*;
public class AppearanceSurfacesTest {
    @Test public void globalChatWallpaperDoesNotBecomeListWallpaper(){AppearanceConfig c=new AppearanceConfig();c.edit("global").set("wallpaper.file","chat");assertNull(AppearanceSurfaces.list(c.resolve(AppearanceConfig.Context.direct(0,0))).get("wallpaper.file"));}
    @Test public void explicitListAndBannerDomainsAreIndependent(){AppearanceConfig c=new AppearanceConfig();c.edit("global").set("wallpaper.file","chat");c.edit("global").set("list.wallpaper.file","list");c.edit("global").set("banner.wallpaper.file","banner");c.edit("global").color(false,"list.chat_wallpaper",123);c.edit("global").color(true,"banner.chat_wallpaper",456);AppearanceConfig.Resolved r=c.resolve(AppearanceConfig.Context.direct(0,0));assertEquals("list",AppearanceSurfaces.list(r).get("wallpaper.file"));assertEquals("banner",AppearanceSurfaces.banner(r).get("wallpaper.file"));assertEquals(Integer.valueOf(123),AppearanceSurfaces.list(r).color(false,"chat_wallpaper"));assertEquals(Integer.valueOf(456),AppearanceSurfaces.banner(r).color(true,"chat_wallpaper"));assertEquals("chat",r.get("wallpaper.file"));}
    @Test public void aSectionWallpaperCanSupplyTheSectionListWithoutChangingGlobalList(){String id="b8348b88-aac9-4f3c-85f7-bb44b7e2b967";AppearanceConfig c=new AppearanceConfig();c.edit("section:"+id).set("wallpaper.file","section");assertEquals("section",AppearanceSurfaces.list(c.resolve(new AppearanceConfig.Context(id,null,0,0))).get("wallpaper.file"));assertNull(AppearanceSurfaces.list(c.resolve(AppearanceConfig.Context.direct(0,0))).get("wallpaper.file"));}
    @Test public void circlePaletteInheritsGlobalButDoesNotLeakAnotherSection(){String first="b8348b88-aac9-4f3c-85f7-bb44b7e2b967",second="b8348b88-aac9-4f3c-85f7-bb44b7e2b968";AppearanceConfig c=new AppearanceConfig();c.edit("global").color(false,"section.badge",10);c.edit("section:"+first).color(false,"section.background",20);c.edit("section:"+first).color(true,"section.background",30);AppearanceConfig restored=AppearanceConfig.decode(c.encode());AppearanceConfig.Resolved a=restored.resolve(new AppearanceConfig.Context(first,null,0,0)),b=restored.resolve(new AppearanceConfig.Context(second,null,0,0));assertEquals(Integer.valueOf(10),a.color(false,"section.badge"));assertEquals(Integer.valueOf(20),a.color(false,"section.background"));assertEquals(Integer.valueOf(30),a.color(true,"section.background"));assertNull(b.color(false,"section.background"));assertEquals(Integer.valueOf(10),b.color(false,"section.badge"));assertEquals("section:"+first,a.origins.get("light.section.background"));}
    @Test public void profileBannerDoesNotChangeChatOrAnotherProfile(){AppearanceConfig c=new AppearanceConfig();c.edit("global").color(false,"banner.chat_wallpaper",1);c.edit("profile:42").color(false,"banner.chat_wallpaper",2);c.edit("profile:42").set("banner.height","320");AppearanceConfig restored=AppearanceConfig.decode(c.encode());assertEquals(Integer.valueOf(2),AppearanceSurfaces.banner(restored.resolveProfile(42)).color(false,"chat_wallpaper"));assertEquals(Integer.valueOf(1),AppearanceSurfaces.banner(restored.resolveProfile(43)).color(false,"chat_wallpaper"));assertNull(restored.resolve(AppearanceConfig.Context.direct(42,0)).get("banner.height"));assertEquals("320",restored.resolveProfile(42).get("banner.height"));}
}
